import React from 'react';
import {
  View,
  Text,
  ScrollView,
  TextInput,
  Platform,
  StyleSheet,
} from 'react-native';
import { Activity, Heart, Mail } from 'lucide-react-native';

type Props = {
  relativeEmail: string;
  setRelativeEmail: (val: string) => void;
};

const OnboardingScreen: React.FC<Props> = ({
  relativeEmail,
  setRelativeEmail,
}) => {
  return (
    <ScrollView
      style={{ flex: 1 }}
      contentContainerStyle={{ paddingBottom: 24 }}
    >
      {/* HERO CHÀO MỪNG */}
      <View style={styles.heroCard}>
        <View style={styles.heroLeft}>
          <Text style={styles.heroTitle}>Chào mừng đến PicoBP 💙</Text>
          <Text style={styles.heroSubtitle}>
            Ứng dụng hỗ trợ theo dõi huyết áp với thiết bị đo ESP32 kết nối trực
            tiếp qua USB.
          </Text>
        </View>
        <View style={styles.heroAvatar}>
          <Heart size={30} color="#ec4899" />
        </View>
      </View>

      {/* EMAIL NGƯỜI DÙNG / NGƯỜI THÂN */}
      <View style={styles.sectionCard}>
        <View style={styles.sectionHeaderRow}>
          <Mail size={18} color="#0f766e" />
          <Text style={styles.sectionTitle}>
            Email của bạn / người thân (tùy chọn)
          </Text>
        </View>
        <Text style={styles.sectionText}>
          Bạn có thể nhập{' '}
          <Text style={{ fontWeight: '700' }}>
            email của bạn hoặc người thân
          </Text>{' '}
          để sau này nhận thông báo khi huyết áp bất thường.
        </Text>
        <Text style={[styles.sectionText, { marginTop: 4 }]}>
          Nếu không muốn dùng chức năng này, bạn có thể bỏ trống và tiếp tục sử
          dụng app bình thường.
        </Text>

        <TextInput
          placeholder="ví dụ: meba@gmail.com"
          placeholderTextColor="#9ca3af"
          style={styles.input}
          value={relativeEmail}
          onChangeText={setRelativeEmail}
          keyboardType="email-address"
          autoCapitalize="none"
        />
        <Text style={styles.helperText}>
          * Email hiện chỉ được lưu cục bộ trên máy bạn và dùng cho các tính
          năng cảnh báo sức khỏe ở phiên bản sau.
        </Text>
      </View>

      {/* HƯỚNG DẪN ĐO HUYẾT ÁP */}
      <View style={styles.sectionCard}>
        <View style={styles.sectionHeaderRow}>
          <Activity size={18} color="#0f766e" />
          <Text style={styles.sectionTitle}>Cách thức đo huyết áp</Text>
        </View>

        {[
          'Cắm ESP32 vào điện thoại bằng cáp OTG. Khi hiện popup xin quyền USB, chọn OK/Allow.',
          'Ngồi trên ghế, lưng tựa, tay đặt ngang tim, thư giãn và không nói chuyện trong lúc đo.',
          'Chuyển sang tab “ĐO USB” và nhấn nút “Bắt đầu đo qua USB”.',
          'Chờ kết quả SYS/DIA, MAP và nhịp tim hiển thị. Nếu chỉ số quá cao, ứng dụng sẽ đưa ra cảnh báo.',
        ].map((text, idx) => (
          <View key={idx} style={styles.stepRow}>
            <View style={styles.stepBullet}>
              <Text style={styles.stepNumber}>{idx + 1}</Text>
            </View>
            <Text style={styles.sectionText}>{text}</Text>
          </View>
        ))}
      </View>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  heroCard: {
    flexDirection: 'row',
    backgroundColor: '#0ea5e9', // xanh da trời
    borderRadius: 20,
    padding: 16,
    marginBottom: 14,
    alignItems: 'center',
  },
  heroLeft: { flex: 1 },
  heroTitle: { fontSize: 18, fontWeight: '700', color: '#ecfeff' },
  heroSubtitle: { marginTop: 6, fontSize: 12, color: '#e0f2fe' },
  heroAvatar: {
    width: 52,
    height: 52,
    borderRadius: 999,
    backgroundColor: '#fdf2f8',
    alignItems: 'center',
    justifyContent: 'center',
    marginLeft: 10,
  },
  sectionCard: {
    backgroundColor: '#ffffff',
    borderRadius: 18,
    padding: 14,
    marginBottom: 12,
    shadowColor: '#000',
    shadowOpacity: 0.05,
    shadowOffset: { width: 0, height: 2 },
    shadowRadius: 6,
    elevation: 2,
  },
  sectionHeaderRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 6,
  },
  sectionTitle: {
    marginLeft: 6,
    fontSize: 14,
    fontWeight: '700',
    color: '#111827',
  },
  sectionText: {
    fontSize: 12,
    color: '#4b5563',
    marginTop: 2,
  },
  input: {
    marginTop: 8,
    borderRadius: 10,
    borderWidth: 1,
    borderColor: '#d1d5db',
    paddingHorizontal: 10,
    paddingVertical: Platform.select({ ios: 10, android: 6, default: 8 }),
    fontSize: 13,
    color: '#111827',
    backgroundColor: '#f9fafb',
  },
  helperText: {
    marginTop: 6,
    fontSize: 11,
    color: '#6b7280',
  },
  stepRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    marginTop: 6,
  },
  stepBullet: {
    width: 20,
    height: 20,
    borderRadius: 999,
    backgroundColor: '#f472b6', // hồng
    alignItems: 'center',
    justifyContent: 'center',
    marginRight: 8,
    marginTop: 2,
  },
  stepNumber: {
    color: '#ecfeff',
    fontSize: 11,
    fontWeight: '700',
  },
});

export default OnboardingScreen;
