// src/screens/MeasureScreen.tsx
import React from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
} from 'react-native';
import { Activity, AlertCircle, Check, Heart } from 'lucide-react-native';
import { Reading } from '../hooks/useUsbSerial';

type Props = {
  usbServiceStarted: boolean;
  usbAttached: boolean;
  connected: boolean;
  isMeasuring: boolean;
  lastReading: Reading;
  log: string[];
  statusText: string;
  onStartMeasure: () => void;
};

const MeasureScreen: React.FC<Props> = ({
  usbServiceStarted,
  usbAttached,
  connected,
  isMeasuring,
  lastReading,
  log,
  statusText,
  onStartMeasure,
}) => {
  return (
    <ScrollView
      style={styles.container}
      contentContainerStyle={{ paddingBottom: 24 }}
    >
      {/* trạng thái tổng */}
      <View style={styles.statusBar}>
        <Text style={styles.statusLabel}>Trạng thái:</Text>
        <Text style={styles.statusValue}>{statusText}</Text>
      </View>

      {/* 3 ô trạng thái nhỏ */}
      <View style={styles.statusGrid}>
        <StatusChip
          label="USB Service"
          value={usbServiceStarted ? 'Sẵn sàng' : 'Chưa khởi tạo'}
          active={usbServiceStarted}
        />
        <StatusChip
          label="Thiết bị"
          value={usbAttached ? 'Đã gắn cáp' : 'Chưa gắn thiết bị'}
          active={usbAttached}
        />
        <StatusChip
          label="Serial"
          value={connected ? 'Đã kết nối' : 'Chờ kết nối'}
          active={connected}
        />
      </View>

      {/* 3 card giá trị huyết áp */}
      <View style={styles.cardList}>
        <MetricCard
          title="Tâm thu (SYS)"
          unit="mmHg"
          value={lastReading.sys}
          heartColor="#fb7185" // hồng/đỏ
        />
        <MetricCard
          title="Tâm trương (DIA)"
          unit="mmHg"
          value={lastReading.dia}
          heartColor="#facc15" // vàng
        />
        <MetricCard
          title="Áp suất trung bình (MAP)"
          unit="mmHg"
          value={lastReading.map}
          heartColor="#22c55e" // xanh lá
        />
      </View>

      {/* nhịp tim */}
      <View style={styles.pulseCard}>
        <View style={{ flexDirection: 'row', alignItems: 'center' }}>
          <Heart size={18} color="#ec4899" />
          <Text style={styles.pulseTitle}> Nhịp tim</Text>
        </View>
        <Text style={styles.pulseValue}>
          {lastReading.pulse != null ? lastReading.pulse : '--'}
        </Text>
        <Text style={styles.pulseUnit}>BPM</Text>
      </View>

      {/* nút đo */}
      <TouchableOpacity
        style={[
          styles.button,
          (!usbServiceStarted || isMeasuring) && styles.buttonDisabled,
        ]}
        onPress={onStartMeasure}
        disabled={!usbServiceStarted || isMeasuring}
      >
        <Text style={styles.buttonIcon}>∿</Text>
        <Text style={styles.buttonText}>
          {isMeasuring ? 'Đang đo...' : 'Bắt đầu đo qua USB'}
        </Text>
      </TouchableOpacity>

      {/* hướng dẫn */}
      <View style={styles.infoBox}>
        <View style={styles.infoHeader}>
          {connected ? (
            <Check size={16} color="#16a34a" />
          ) : (
            <AlertCircle size={16} color="#f97316" />
          )}
          <Text style={styles.infoTitle}> Hướng dẫn nhanh</Text>
        </View>
        <Text style={styles.infoText}>
          1. Cắm ESP32 vào điện thoại bằng cáp OTG.
        </Text>
        <Text style={styles.infoText}>
          2. Khi hiện popup xin quyền USB, chọn{' '}
          <Text style={{ fontWeight: '700' }}>OK / Allow</Text>.
        </Text>
        <Text style={styles.infoText}>
          3. ESP32 gửi JSON theo từng dòng, ví dụ:
        </Text>
        <Text style={styles.code}>
          {'{"type":"measurement_result","sys":123,"dia":80,"pulse":70}\\n'}
        </Text>
      </View>

      {/* log */}
      <View style={styles.logHeaderRow}>
        <Text style={styles.logTitle}>Nhật ký kết nối</Text>
        <View style={styles.logBadge}>
          <Text style={styles.logBadgeText}>{log.length}</Text>
        </View>
      </View>
      <View style={styles.logBox}>
        <ScrollView
          style={{ maxHeight: 150 }}
          contentContainerStyle={{ paddingVertical: 6 }}
        >
          {log.map((l, i) => (
            <Text key={i} style={styles.logLine}>
              {l}
            </Text>
          ))}
        </ScrollView>
      </View>
    </ScrollView>
  );
};

type StatusChipProps = {
  label: string;
  value: string;
  active: boolean;
};

const StatusChip: React.FC<StatusChipProps> = ({ label, value, active }) => (
  <View style={styles.statusChip}>
    <View
      style={[
        styles.statusDot,
        { backgroundColor: active ? '#22c55e' : '#9ca3af' },
      ]}
    />
    <View style={{ flex: 1 }}>
      <Text style={styles.statusChipLabel}>{label}</Text>
      <Text style={styles.statusChipValue}>{value}</Text>
    </View>
  </View>
);

type MetricCardProps = {
  title: string;
  unit: string;
  value?: number;
  heartColor: string;
};

const MetricCard: React.FC<MetricCardProps> = ({
  title,
  unit,
  value,
  heartColor,
}) => (
  <View style={styles.metricCard}>
    <View style={styles.metricHeader}>
      <View>
        <Text style={styles.metricTitle}>{title}</Text>
        <Text style={styles.metricUnit}>{unit}</Text>
      </View>
      <View
        style={[styles.metricHeart, { backgroundColor: `${heartColor}22` }]}
      >
        <Heart size={18} color={heartColor} />
      </View>
    </View>
    <View style={styles.metricValueRow}>
      <Text style={styles.metricValue}>{value != null ? value : '---'}</Text>
      {value == null && (
        <Text style={styles.metricPlaceholder}>Chờ dữ liệu…</Text>
      )}
    </View>
  </View>
);

